// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CameraBinding) predicate.CameraBinding {
	return predicate.CameraBinding(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CameraBinding) predicate.CameraBinding {
	return predicate.CameraBinding(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CameraBinding) predicate.CameraBinding {
	return predicate.CameraBinding(sql.NotPredicates(p))
}
